  1→import { useEffect, useState } from "react";
  2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
  3→import { useLoaderData, useFetcher, useNavigate } from "react-router";
  4→import { useAppBridge } from "@shopify/app-bridge-react";
  5→import { authenticate } from "../shopify.server";
  6→import db from "../db.server";
  7→import { getPlan, hasFeature } from "../lib/plans";
  8→import {
  9→  Page,
 10→  Card,
 11→  BlockStack,
 12→  InlineStack,
 13→  Text,
 14→  Badge,
 15→  Button,
 16→  ButtonGroup,
 17→  Banner,
 18→  Divider,
 19→  InlineGrid,
 20→  TextField,
 21→  Select,
 22→  Checkbox,
 23→} from "@shopify/polaris";
 24→
 25→// ---------------------------------------------------------------------------
 26→// Types
 27→// ---------------------------------------------------------------------------
 28→
 29→// ---------------------------------------------------------------------------
 30→// Loader
 31→// ---------------------------------------------------------------------------
 32→
 33→export const loader = async ({ request }: LoaderFunctionArgs) => {
 34→  const { session } = await authenticate.admin(request);
 35→  const shop = session.shop;
 36→
 37→  const [
 38→    chartCount,
 39→    assignmentCount,
 40→    widgetConfig,
 41→    recommenderConfig,
 42→    subscription,
 43→  ] = await Promise.all([
 44→    db.sizeChart.count({ where: { shop } }),
 45→    db.chartAssignment.count({ where: { shop } }),
 46→    db.widgetConfig.findUnique({ where: { shop } }),
 47→    db.recommenderConfig.findUnique({ where: { shop } }),
 48→    db.subscription.findUnique({ where: { shop } }),
 49→  ]);
 50→
 51→  const plan = getPlan(subscription?.planId ?? "free");
 52→
 53→  return {
 54→    shop,
 55→    chartCount,
 56→    assignmentCount,
 57→    hasWidgetConfig: widgetConfig !== null,
 58→    widgetDisplayMode: widgetConfig?.displayMode ?? null,
 59→    hasRecommenderConfig: recommenderConfig !== null,
 60→    recommenderEnabled: recommenderConfig?.enabled ?? false,
 61→    plan,
 62→    isPriority: hasFeature(plan.id, "prioritySupport"),
 63→    isFreePlan: plan.id === "free",
 64→  };
 65→};
 66→
 67→// ---------------------------------------------------------------------------
 68→// Action
 69→// ---------------------------------------------------------------------------
 70→
 71→export const action = async ({ request }: ActionFunctionArgs) => {
 72→  const { session } = await authenticate.admin(request);
 73→  const shop = session.shop;
 74→  const formData = await request.formData();
 75→  const intent = formData.get("intent") as string;
 76→
 77→  try {
 78→    switch (intent) {
 79→      case "export-data": {
 80→        const charts = await db.sizeChart.findMany({
 81→          where: { shop },
 82→          include: { assignments: true },
 83→        });
 84→        const payload = {
 85→          exportedAt: new Date().toISOString(),
 86→          shop,
 87→          charts: charts.map((c) => ({
 88→            id: c.id,
 89→            name: c.name,
 90→            type: c.type,
 91→            category: c.category,
 92→            data: c.data,
 93→            isDefault: c.isDefault,
 94→            status: c.status,
 95→            createdAt: c.createdAt.toISOString(),
 96→            assignments: c.assignments.map((a) => ({
 97→              assignmentType: a.assignmentType,
 98→              assignmentValue: a.assignmentValue,
 99→            })),
100→          })),
101→        };
102→        return {
103→          ok: true,
104→          intent: "export-data",
105→          message: `${charts.length} chart${charts.length === 1 ? "" : "s"} exported`,
106→          exportData: JSON.stringify(payload, null, 2),
107→        };
108→      }
109→
110→      case "import-data": {
111→        const subscription = await db.subscription.findUnique({ where: { shop } });
112→        const plan = getPlan(subscription?.planId ?? "free");
113→        if (!hasFeature(plan.id, "csvImport")) {
114→          return { error: "Import requires the Starter plan or above", intent: "import-data" };
115→        }
116→
117→        const jsonRaw = formData.get("importJson") as string;
118→        if (!jsonRaw?.trim()) {
119→          return { error: "No JSON data provided", intent: "import-data" };
120→        }
121→        let parsed: { charts?: Array<{
122→          name: string;
123→          type?: string;
124→          category?: string;
125→          data?: string;
126→          isDefault?: boolean;
127→          status?: string;
128→          assignments?: Array<{ assignmentType: string; assignmentValue: string }>;
129→        }> };
130→        try {
131→          parsed = JSON.parse(jsonRaw) as typeof parsed;
132→        } catch {
133→          return { error: "Invalid JSON format", intent: "import-data" };
134→        }
135→        if (!Array.isArray(parsed.charts)) {
136→          return { error: "JSON must contain a 'charts' array", intent: "import-data" };
137→        }
138→        let imported = 0;
139→        for (const chart of parsed.charts) {
140→          if (!chart.name) continue;
141→          const existing = await db.sizeChart.findFirst({
142→            where: { shop, name: chart.name },
143→          });
144→          if (existing) continue;
145→          await db.sizeChart.create({
146→            data: {
147→              shop,
148→              name: chart.name,
149→              type: chart.type ?? "table",
150→              category: chart.category ?? "general",
151→              data: chart.data ?? "{}",
152→              isDefault: chart.isDefault ?? false,
153→              status: chart.status ?? "draft",
154→              assignments: chart.assignments
155→                ? {
156→                    create: chart.assignments.map((a) => ({
157→                      shop,
158→                      assignmentType: a.assignmentType,
159→                      assignmentValue: a.assignmentValue,
160→                    })),
161→                  }
162→                : undefined,
163→            },
164→          });
165→          imported++;
166→        }
167→        return {
168→          ok: true,
169→          intent: "import-data",
170→          message: `${imported} chart${imported === 1 ? "" : "s"} imported successfully`,
171→        };
172→      }
173→
174→      case "reset-widget": {
175→        await db.widgetConfig.deleteMany({ where: { shop } });
176→        return { ok: true, intent: "reset-widget", message: "Widget settings reset to defaults" };
177→      }
178→
179→      case "reset-analytics": {
180→        const deleted = await db.analyticsEvent.deleteMany({ where: { shop } });
181→        return {
182→          ok: true,
183→          intent: "reset-analytics",
184→          message: `${deleted.count} analytics event${deleted.count === 1 ? "" : "s"} cleared`,
185→        };
186→      }
187→
188→      case "delete-all-charts": {
189→        const confirm = formData.get("confirmText") as string;
190→        if (confirm !== "DELETE") {
191→          return { error: "Type DELETE to confirm", intent: "delete-all-charts" };
192→        }
193→        const deleted = await db.sizeChart.deleteMany({ where: { shop } });
194→        return {
195→          ok: true,
196→          intent: "delete-all-charts",
197→          message: `${deleted.count} chart${deleted.count === 1 ? "" : "s"} deleted`,
198→        };
199→      }
200→
201→      default:
202→        return { error: "Unknown action", intent };
203→    }
204→  } catch (error) {
205→    const message = error instanceof Error ? error.message : "An unexpected error occurred";
206→    return { error: message, intent };
207→  }
208→};
209→
210→// ---------------------------------------------------------------------------
211→// Sub-components
212→// ---------------------------------------------------------------------------
213→
214→function StatCard({
215→  label,
216→  value,
217→  sub,
218→}: {
219→  label: string;
220→  value: string | number;
221→  sub?: string;
222→}) {
223→  return (
224→    <Card>
225→      <BlockStack gap="200">
226→        <Text as="h2" variant="headingMd" fontWeight="bold">{String(value)}</Text>
227→        <Text as="p" variant="bodyMd" tone="subdued">{label}</Text>
228→        {sub && <Text as="p" variant="bodyMd" tone="subdued">{sub}</Text>}
229→      </BlockStack>
230→    </Card>
231→  );
232→}
233→
234→function StatusRow({
235→  label,
236→  configured,
237→  configuredLabel,
238→  notConfiguredLabel,
239→}: {
240→  label: string;
241→  configured: boolean;
242→  configuredLabel: string;
243→  notConfiguredLabel: string;
244→}) {
245→  return (
246→    <InlineStack gap="400" blockAlign="center">
247→      <Text as="p" variant="bodyMd">{label}</Text>
248→      <Badge tone={configured ? "success" : "enabled"}>
249→        {configured ? configuredLabel : notConfiguredLabel}
250→      </Badge>
251→    </InlineStack>
252→  );
253→}
254→
255→// ---------------------------------------------------------------------------
256→// Main Component
257→// ---------------------------------------------------------------------------
258→
259→export default function Settings() {
260→  const {
261→    shop,
262→    chartCount,
263→    assignmentCount,
264→    hasWidgetConfig,
265→    widgetDisplayMode,
266→    hasRecommenderConfig,
267→    recommenderEnabled,
268→    plan,
269→    isPriority,
270→    isFreePlan,
271→  } = useLoaderData<typeof loader>();
272→
273→  const fetcher = useFetcher<typeof action>();
274→  const shopify = useAppBridge();
275→  const navigate = useNavigate();
276→  const isLoading = fetcher.state !== "idle";
277→
278→  // General settings (client-only — persisted in localStorage for now)
279→  const [unitSystem, setUnitSystem] = useState<string>("cm");
280→  const [defaultCategory, setDefaultCategory] = useState<string>("general");
281→  const [autoPublish, setAutoPublish] = useState<boolean>(false);
282→
283→  // Import text area
284→  const [importJson, setImportJson] = useState<string>("");
285→
286→  // Danger zone confirm text
287→  const [deleteConfirm, setDeleteConfirm] = useState<string>("");
288→
289→  // Export download trigger
290→  const [exportedJson, setExportedJson] = useState<string | null>(null);
291→
292→  useEffect(() => {
293→    if (!fetcher.data) return;
294→
295→    if ("ok" in fetcher.data) {
296→      shopify.toast.show(fetcher.data.message ?? "Done");
297→
298→      if (fetcher.data.intent === "export-data" && "exportData" in fetcher.data) {
299→        setExportedJson(fetcher.data.exportData as string);
300→      }
301→
302→      if (fetcher.data.intent === "import-data") {
303→        setImportJson("");
304→      }
305→
306→      if (fetcher.data.intent === "delete-all-charts") {
307→        setDeleteConfirm("");
308→      }
309→    } else if ("error" in fetcher.data) {
310→      shopify.toast.show(fetcher.data.error ?? "An error occurred", { isError: true });
311→    }
312→  }, [fetcher.data, shopify]);
313→
314→  // Trigger browser download when export data is ready
315→  useEffect(() => {
316→    if (!exportedJson) return;
317→    const blob = new Blob([exportedJson], { type: "application/json" });
318→    const url = URL.createObjectURL(blob);
319→    const a = document.createElement("a");
320→    a.href = url;
321→    a.download = `size-charts-${shop}-${new Date().toISOString().slice(0, 10)}.json`;
322→    a.click();
323→    URL.revokeObjectURL(url);
324→    setExportedJson(null);
325→  }, [exportedJson, shop]);
326→
327→  const submitIntent = (intent: string, extra?: Record<string, string>) => {
328→    const fd = new FormData();
329→    fd.set("intent", intent);
330→    if (extra) {
331→      for (const [k, v] of Object.entries(extra)) fd.set(k, v);
332→    }
333→    fetcher.submit(fd, { method: "post" });
334→  };
335→
336→  const CATEGORIES = [
337→    "general",
338→    "tops",
339→    "bottoms",
340→    "dresses",
341→    "shoes",
342→    "kids",
343→    "rings",
344→    "sportswear",
345→    "outerwear",
346→  ];
347→
348→  const unitOptions = [
349→    { label: "Centimeters (cm)", value: "cm" },
350→    { label: "Inches (in)", value: "in" },
351→  ];
352→
353→  const categoryOptions = CATEGORIES.map((cat) => ({
354→    label: cat.charAt(0).toUpperCase() + cat.slice(1),
355→    value: cat,
356→  }));
357→
358→  return (
359→    <Page
360→      title="Settings"
361→      backAction={{ onAction: () => navigate("/app") }}
362→      primaryAction={
363→        <Button variant="primary" url="/app/pricing">
364→          {isFreePlan ? "Upgrade plan" : "Manage billing"}
365→        </Button>
366→      }
367→    >
368→      <BlockStack gap="600">
369→
370→        {/* ================================================================ */}
371→        {/* SECTION 1 — Account Overview                                      */}
372→        {/* ================================================================ */}
373→        <Card>
374→          <BlockStack gap="400">
375→            <Text as="h2" variant="headingMd" fontWeight="bold">Account Overview</Text>
376→
377→            <BlockStack gap="200">
378→              <InlineStack gap="200" blockAlign="center">
379→                <Text as="p" variant="bodyMd">Store</Text>
380→                <Text as="p" variant="bodyMd" tone="subdued">{shop}</Text>
381→              </InlineStack>
382→              <Divider />
383→              <InlineStack gap="200" blockAlign="center">
384→                <Text as="p" variant="bodyMd">Current plan</Text>
385→                <Badge tone={isFreePlan ? "enabled" : "success"}>{plan.name}</Badge>
386→                <Text as="p" variant="bodyMd" tone="subdued">
387→                  {plan.price === 0 ? "Free forever" : `$${plan.price}/mo`}
388→                </Text>
389→              </InlineStack>
390→              {isFreePlan && (
391→                <Banner tone="info" title="Upgrade for more features">
392→                  <BlockStack gap="200">
393→                    <Text as="p" variant="bodyMd" tone="subdued">
394→                      Get unlimited charts, auto-assignment, CSV import/export, AI recommender, and analytics.
395→                    </Text>
396→                    <Button variant="primary" url="/app/pricing">View upgrade options</Button>
397→                  </BlockStack>
398→                </Banner>
399→              )}
400→            </BlockStack>
401→
402→            <InlineGrid columns={{ xs: 1, sm: 2 }} gap="400">
403→              <StatCard
404→                label="Size charts"
405→                value={chartCount}
406→                sub={`${plan.limits.maxCharts === -1 ? "Unlimited" : `${chartCount} of ${plan.limits.maxCharts}`} charts`}
407→              />
408→              <StatCard
409→                label="Assignments"
410→                value={assignmentCount}
411→                sub="Products, collections, tags"
412→              />
413→            </InlineGrid>
414→          </BlockStack>
415→        </Card>
416→
417→        {/* ================================================================ */}
418→        {/* SECTION 2 — General Settings                                      */}
419→        {/* ================================================================ */}
420→        <Card>
421→          <BlockStack gap="400">
422→            <Text as="h2" variant="headingMd" fontWeight="bold">General Settings</Text>
423→
424→            <BlockStack gap="200">
425→              <Text as="p" variant="bodyMd">Default unit system</Text>
426→              <Text as="p" variant="bodyMd" tone="subdued">
427→                Sets the default measurement unit for new size charts. Customers can always switch.
428→              </Text>
429→              <Select
430→                label="Default unit system"
431→                labelHidden
432→                options={unitOptions}
433→                value={unitSystem}
434→                onChange={(value) => setUnitSystem(value)}
435→              />
436→            </BlockStack>
437→
438→            <Divider />
439→
440→            <BlockStack gap="200">
441→              <Text as="p" variant="bodyMd">Default chart category</Text>
442→              <Text as="p" variant="bodyMd" tone="subdued">
443→                Pre-selected category when creating a new size chart from scratch.
444→              </Text>
445→              <Select
446→                label="Default chart category"
447→                labelHidden
448→                options={categoryOptions}
449→                value={defaultCategory}
450→                onChange={(value) => setDefaultCategory(value)}
451→              />
452→            </BlockStack>
453→
454→            <Divider />
455→
456→            <InlineStack gap="400" blockAlign="center">
457→              <BlockStack gap="200">
458→                <Text as="p" variant="bodyMd">Auto-publish new charts</Text>
459→                <Text as="p" variant="bodyMd" tone="subdued">
460→                  New charts are immediately set to Active instead of Draft.
461→                </Text>
462→              </BlockStack>
463→              <Checkbox
464→                label="Auto-publish new charts"
465→                labelHidden
466→                checked={autoPublish}
467→                onChange={(checked) => setAutoPublish(checked)}
468→              />
469→            </InlineStack>
470→          </BlockStack>
471→        </Card>
472→
473→        {/* ================================================================ */}
474→        {/* SECTION 3 — Data Management                                       */}
475→        {/* ================================================================ */}
476→        <Card>
477→          <BlockStack gap="400">
478→            <Text as="h2" variant="headingMd" fontWeight="bold">Data Management</Text>
479→
480→            {/* Export */}
481→            <Card>
482→              <BlockStack gap="200">
483→                <Text as="h3" variant="headingMd" fontWeight="bold">Export size charts</Text>
484→                <Text as="p" variant="bodyMd" tone="subdued">
485→                  Download all {chartCount} chart{chartCount === 1 ? "" : "s"} as a JSON file. Includes all assignments and data. Use to back up or migrate to another store.
486→                </Text>
487→                <InlineStack gap="200">
488→                  <Button
489→                    onClick={() => submitIntent("export-data")}
490→                    loading={isLoading && fetcher.formData?.get("intent") === "export-data"}
491→                    disabled={chartCount === 0}
492→                  >
493→                    Export all charts
494→                  </Button>
495→                </InlineStack>
496→                {chartCount === 0 && (
497→                  <Text as="p" variant="bodyMd" tone="subdued">No charts to export.</Text>
498→                )}
499→              </BlockStack>
500→            </Card>
501→
502→            {/* Import */}
503→            <Card>
504→              <BlockStack gap="200">
505→                <Text as="h3" variant="headingMd" fontWeight="bold">Import charts from JSON</Text>
506→                <Text as="p" variant="bodyMd" tone="subdued">
507→                  Paste your exported JSON backup below. Existing charts with the same name are skipped.
508→                </Text>
509→                {!hasFeature(plan.id, "csvImport") && (
510→                  <Banner tone="warning" title="Starter plan required">
511→                    <Text as="p" variant="bodyMd" tone="subdued">
512→                      Import is available on the Starter plan ($4.99/mo) and above.
513→                    </Text>
514→                  </Banner>
515→                )}
516→                <TextField
517→                  label="Import JSON"
518→                  labelHidden
519→                  value={importJson}
520→                  onChange={(value) => setImportJson(value)}
521→                  placeholder='{"charts": [...]}'
522→                  multiline={6}
523→                  autoComplete="off"
524→                  disabled={!hasFeature(plan.id, "csvImport")}
525→                />
526→                <InlineStack gap="200">
527→                  <Button
528→                    variant="primary"
529→                    onClick={() => submitIntent("import-data", { importJson })}
530→                    loading={isLoading && fetcher.formData?.get("intent") === "import-data"}
531→                    disabled={!hasFeature(plan.id, "csvImport") || !importJson.trim()}
532→                  >
533→                    Import charts
534→                  </Button>
535→                </InlineStack>
536→              </BlockStack>
537→            </Card>
538→          </BlockStack>
539→        </Card>
540→
541→        {/* ================================================================ */}
542→        {/* SECTION 4 — Widget Settings Quick Access                          */}
543→        {/* ================================================================ */}
544→        <Card>
545→          <BlockStack gap="400">
546→            <Text as="h2" variant="headingMd" fontWeight="bold">Widget Settings</Text>
547→
548→            <BlockStack gap="200">
549→              <InlineStack gap="200" blockAlign="center">
550→                <Text as="p" variant="bodyMd">Widget status</Text>
551→                <Badge tone={hasWidgetConfig ? "success" : "enabled"}>
552→                  {hasWidgetConfig ? "Configured" : "Using defaults"}
553→                </Badge>
554→              </InlineStack>
555→              {hasWidgetConfig && widgetDisplayMode && (
556→                <InlineStack gap="200" blockAlign="center">
557→                  <Text as="p" variant="bodyMd" tone="subdued">Display mode</Text>
558→                  <Badge tone="info">{widgetDisplayMode}</Badge>
559→                </InlineStack>
560→              )}
561→              <Text as="p" variant="bodyMd" tone="subdued">
562→                {hasWidgetConfig
563→                  ? "Widget is customized with your brand settings."
564→                  : "Widget is using default appearance settings."}
565→              </Text>
566→              <ButtonGroup>
567→                <Button variant="primary" url="/app/widget">Open Widget Customizer</Button>
568→                <Button
569→                  tone="critical"
570→                  onClick={() => submitIntent("reset-widget")}
571→                  loading={isLoading && fetcher.formData?.get("intent") === "reset-widget"}
572→                  disabled={!hasWidgetConfig}
573→                >
574→                  Reset to defaults
575→                </Button>
576→              </ButtonGroup>
577→            </BlockStack>
578→          </BlockStack>
579→        </Card>
580→
581→        {/* ================================================================ */}
582→        {/* SECTION 5 — Danger Zone                                           */}
583→        {/* ================================================================ */}
584→        <Card>
585→          <BlockStack gap="400">
586→            <Text as="h2" variant="headingMd" fontWeight="bold">Danger Zone</Text>
587→
588→            <Banner tone="critical" title="Irreversible actions">
589→              <Text as="p" variant="bodyMd" tone="subdued">
590→                These actions cannot be undone. Proceed with caution.
591→              </Text>
592→            </Banner>
593→
594→            <BlockStack gap="400">
595→              {/* Clear Analytics */}
596→              <Card>
597→                <BlockStack gap="200">
598→                  <Text as="p" variant="bodyMd">Clear analytics data</Text>
599→                  <Text as="p" variant="bodyMd" tone="subdued">
600→                    Permanently delete all chart view events, recommendation events, and conversion data. This cannot be undone.
601→                  </Text>
602→                  <InlineStack gap="200">
603→                    <Button
604→                      tone="critical"
605→                      onClick={() => submitIntent("reset-analytics")}
606→                      loading={isLoading && fetcher.formData?.get("intent") === "reset-analytics"}
607→                    >
608→                      Clear all analytics
609→                    </Button>
610→                  </InlineStack>
611→                </BlockStack>
612→              </Card>
613→
614→              {/* Delete All Charts */}
615→              <Card>
616→                <BlockStack gap="200">
617→                  <Text as="p" variant="bodyMd">Delete all size charts</Text>
618→                  <Text as="p" variant="bodyMd" tone="subdued">
619→                    Permanently delete all {chartCount} size chart{chartCount === 1 ? "" : "s"} and their assignments. Type DELETE below to confirm.
620→                  </Text>
621→                  <TextField
622→                    label='Type "DELETE" to confirm'
623→                    value={deleteConfirm}
624→                    onChange={(value) => setDeleteConfirm(value)}
625→                    placeholder="DELETE"
626→                    autoComplete="off"
627→                  />
628→                  <InlineStack gap="200">
629→                    <Button
630→                      tone="critical"
631→                      onClick={() => submitIntent("delete-all-charts", { confirmText: deleteConfirm })}
632→                      loading={isLoading && fetcher.formData?.get("intent") === "delete-all-charts"}
633→                      disabled={deleteConfirm !== "DELETE" || chartCount === 0}
634→                    >
635→                      Delete all charts
636→                    </Button>
637→                  </InlineStack>
638→                </BlockStack>
639→              </Card>
640→            </BlockStack>
641→          </BlockStack>
642→        </Card>
643→
644→        {/* ================================================================ */}
645→        {/* APP STATUS + SUPPORT (inline)                                      */}
646→        {/* ================================================================ */}
647→        <Card>
648→          <BlockStack gap="400">
649→            <Text as="h2" variant="headingMd" fontWeight="bold">App Status</Text>
650→
651→            <InlineStack gap="400" wrap>
652→              <StatusRow
653→                label="Widget config"
654→                configured={hasWidgetConfig}
655→                configuredLabel="Configured"
656→                notConfiguredLabel="Using defaults"
657→              />
658→              <StatusRow
659→                label="AI Recommender"
660→                configured={recommenderEnabled}
661→                configuredLabel="Enabled"
662→                notConfiguredLabel={hasRecommenderConfig ? "Disabled" : "Not set up"}
663→              />
664→              <StatusRow
665→                label="Theme extension"
666→                configured={chartCount > 0}
667→                configuredLabel="Charts ready"
668→                notConfiguredLabel="No charts yet"
669→              />
670→              <BlockStack gap="100">
