 61→export const loader = async ({ request }: LoaderFunctionArgs) => {
 62→  const { session } = await authenticate.admin(request);
 63→  const shop = session.shop;
 64→
 65→  const [config, subscription, charts] = await Promise.all([
 66→    db.recommenderConfig.findUnique({ where: { shop } }),
 67→    db.subscription.findUnique({ where: { shop } }),
 68→    db.sizeChart.findMany({
 69→      where: { shop, status: "active" },
 70→      select: { id: true, name: true, category: true },
 71→      orderBy: { name: "asc" },
 72→    }),
 73→  ]);
 74→
 75→  const plan = getPlan(subscription?.planId ?? "free");
 76→  const canUseAi = hasFeature(plan.id, "aiRecommender");
 77→  const canUseAdvanced = hasFeature(plan.id, "advancedAi");
 78→
 79→  let bodyTypes = DEFAULT_BODY_TYPES;
 80→  if (config?.bodyTypes) {
 81→    try {
 82→      const saved = JSON.parse(config.bodyTypes) as Array<{ id: string; enabled: boolean }>;
 83→      bodyTypes = DEFAULT_BODY_TYPES.map((bt) => {
 84→        const match = saved.find((s) => s.id === bt.id);
 85→        return match ? { ...bt, enabled: match.enabled } : bt;
 86→      });
 87→    } catch {
 88→      bodyTypes = DEFAULT_BODY_TYPES;
 89→    }
 90→  }
 91→
 92→  let sizingRules: Record<string, string> = {};
 93→  if (config?.sizingRules) {
 94→    try {
 95→      sizingRules = JSON.parse(config.sizingRules) as Record<string, string>;
 96→    } catch {
 97→      sizingRules = {};
 98→    }
 99→  }
100→
101→  const fitPreference = (sizingRules.fitPreference as string) ?? DEFAULT_FIT_PREFERENCE;
102→  const betweenSizes = (sizingRules.betweenSizes as string) ?? "larger";
103→
104→  return {
105→    config: {
106→      enabled: config?.enabled ?? false,
107→      algorithm: config?.algorithm ?? DEFAULT_ALGORITHM,
108→    },
109→    bodyTypes,
110→    fitPreference,
111→    betweenSizes,
112→    plan,
113→    canUseAi,
114→    canUseAdvanced,
115→    charts,
116→  };
117→};
