123→export const action = async ({ request }: ActionFunctionArgs) => {
124→  const { session } = await authenticate.admin(request);
125→  const shop = session.shop;
126→  const formData = await request.formData();
127→  const intent = formData.get("intent") as string;
128→
129→  try {
130→    switch (intent) {
131→      case "toggle": {
132→        const subscription = await db.subscription.findUnique({ where: { shop } });
133→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
134→          return { error: "AI recommender requires Growth plan or higher", intent };
135→        }
136→        const current = await db.recommenderConfig.findUnique({ where: { shop } });
137→        const newEnabled = !current?.enabled;
138→        await db.recommenderConfig.upsert({
139→          where: { shop },
140→          update: { enabled: newEnabled },
141→          create: { shop, enabled: newEnabled },
142→        });
143→        return {
144→          ok: true,
145→          intent,
146→          enabled: newEnabled,
147→          message: newEnabled ? "AI Recommender enabled" : "AI Recommender disabled",
148→        };
149→      }
150→
151→      case "update-settings": {
152→        const subscription = await db.subscription.findUnique({ where: { shop } });
153→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
154→          return { error: "AI recommender requires Growth plan or higher", intent };
155→        }
156→        const algorithm = (formData.get("algorithm") as string) || DEFAULT_ALGORITHM;
157→        await db.recommenderConfig.upsert({
158→          where: { shop },
159→          update: { algorithm },
160→          create: { shop, algorithm },
161→        });
162→        return { ok: true, intent, message: "Algorithm updated" };
163→      }
164→
165→      case "save-body-types": {
166→        const subscription = await db.subscription.findUnique({ where: { shop } });
167→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
168→          return { error: "AI recommender requires Growth plan or higher", intent };
169→        }
170→        const bodyTypesRaw = formData.get("bodyTypes") as string;
171→        if (!bodyTypesRaw) return { error: "No body types data", intent };
172→        await db.recommenderConfig.upsert({
173→          where: { shop },
174→          update: { bodyTypes: bodyTypesRaw },
175→          create: { shop, bodyTypes: bodyTypesRaw },
176→        });
177→        return { ok: true, intent, message: "Body types saved" };
178→      }
179→
180→      case "save-sizing-rules": {
181→        const subscription = await db.subscription.findUnique({ where: { shop } });
182→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
183→          return { error: "AI recommender requires Growth plan or higher", intent };
184→        }
185→        const fitPreference = (formData.get("fitPreference") as string) || DEFAULT_FIT_PREFERENCE;
186→        const betweenSizes = (formData.get("betweenSizes") as string) || "larger";
187→        const rules = JSON.stringify({ fitPreference, betweenSizes });
188→        await db.recommenderConfig.upsert({
189→          where: { shop },
190→          update: { sizingRules: rules },
191→          create: { shop, sizingRules: rules },
192→        });
193→        return { ok: true, intent, message: "Sizing rules saved" };
194→      }
195→
196→      case "test-recommendation": {
197→        const subscription = await db.subscription.findUnique({ where: { shop } });
198→        if (!hasFeature(getPlan(subscription?.planId ?? "free").id, "aiRecommender")) {
199→          return { error: "AI recommender requires Growth plan or higher", intent };
200→        }
201→
202→        const heightCm = parseFloat(formData.get("height") as string);
203→        const weightKg = parseFloat(formData.get("weight") as string);
204→        const bodyType = (formData.get("bodyType") as string) || "regular";
205→        const fitPref = (formData.get("fitPreference") as string) || DEFAULT_FIT_PREFERENCE;
206→
207→        if (isNaN(heightCm) || isNaN(weightKg) || heightCm < 100 || heightCm > 250 || weightKg < 30 || weightKg > 250) {
208→          return { error: "Please enter valid height (100–250 cm) and weight (30–250 kg)", intent };
209→        }
210→
211→        // Statistical body proportion model (basic algorithm)
212→        const bmi = weightKg / ((heightCm / 100) ** 2);
213→
214→        const bodyTypeMultipliers: Record<string, { bust: number; waist: number; hips: number }> = {
215→          slim:    { bust: 0.52, waist: 0.43, hips: 0.54 },
216→          regular: { bust: 0.54, waist: 0.46, hips: 0.57 },
217→          athletic:{ bust: 0.56, waist: 0.44, hips: 0.56 },
218→          plus:    { bust: 0.59, waist: 0.52, hips: 0.62 },
219→          petite:  { bust: 0.52, waist: 0.44, hips: 0.55 },
220→        };
221→
222→        const fitBias: Record<string, number> = {
223→          "tight": -2,
224→          "true-to-size": 0,
225→          "relaxed": 2,
226→          "oversized": 4,
227→        };
228→
229→        const mult = bodyTypeMultipliers[bodyType] ?? bodyTypeMultipliers.regular;
230→        const bias = fitBias[fitPref] ?? 0;
231→
232→        const bust = Math.round(heightCm * mult.bust + bias);
233→        const waist = Math.round(heightCm * mult.waist + (bmi - 22) * 0.5 + bias);
234→        const hips = Math.round(heightCm * mult.hips + bias);
235→
236→        // Size chart lookup (bust-based for tops/general)
237→        const sizes = [
238→          { label: "XS", bustMin: 76, bustMax: 83 },
239→          { label: "S",  bustMin: 84, bustMax: 91 },
240→          { label: "M",  bustMin: 92, bustMax: 99 },
241→          { label: "L",  bustMin: 100, bustMax: 107 },
242→          { label: "XL", bustMin: 108, bustMax: 115 },
243→          { label: "2XL",bustMin: 116, bustMax: 123 },
244→          { label: "3XL",bustMin: 124, bustMax: 131 },
245→        ];
246→
247→        const matched = sizes.find((s) => bust >= s.bustMin && bust <= s.bustMax);
248→        const matchedIdx = matched ? sizes.indexOf(matched) : 2;
249→        const size = matched?.label ?? "M";
250→        const confidence = matched
251→          ? Math.round(90 - Math.abs(bust - (matched.bustMin + matched.bustMax) / 2) * 0.8)
252→          : 65;
253→
254→        const alternatives: string[] = [];
255→        if (matchedIdx > 0) alternatives.push(sizes[matchedIdx - 1].label);
256→        if (matchedIdx < sizes.length - 1) alternatives.push(sizes[matchedIdx + 1].label);
257→
258→        return {
259→          ok: true,
260→          intent,
261→          testResult: { size, confidence, alternatives, bust, waist, hips } as TestResult,
262→          message: `Recommended size: ${size}`,
263→        };
264→      }
265→
266→      default:
267→        return { error: "Unknown action", intent };
268→    }
269→  } catch (error) {
270→    const message = error instanceof Error ? error.message : "An unexpected error occurred";
271→    return { error: message, intent };
272→  }
273→};
