  1→import { useState } from "react";
  2→import type { LoaderFunctionArgs } from "react-router";
  3→import { useLoaderData, useFetcher, useNavigate } from "react-router";
  4→import {
  5→  Page,
  6→  Layout,
  7→  Card,
  8→  BlockStack,
  9→  InlineStack,
 10→  Text,
 11→  Badge,
 12→  Button,
 13→  ButtonGroup,
 14→  Banner,
 15→  Box,
 16→  InlineGrid,
 17→  Tooltip,
 18→} from "@shopify/polaris";
 19→import { authenticate } from "../shopify.server";
 20→import db from "../db.server";
 21→import { getPlan, hasFeature } from "../lib/plans";
 22→
 23→// ---------------------------------------------------------------------------
 24→// Types
 25→// ---------------------------------------------------------------------------
 26→
 27→interface DailyDataPoint {
 28→  label: string;
 29→  value: number;
 30→}
 31→
 32→interface TopChart {
 33→  chartId: string | null;
 34→  chartName: string;
 35→  views: number;
 36→  rank: number;
 37→}
 38→
 39→// ---------------------------------------------------------------------------
 40→// Loader
 41→// ---------------------------------------------------------------------------
 42→
 43→export const loader = async ({ request }: LoaderFunctionArgs) => {
 44→  const { session } = await authenticate.admin(request);
 45→  const shop = session.shop;
 46→
 47→  const url = new URL(request.url);
 48→  const fromParam = url.searchParams.get("from");
 49→  const toParam = url.searchParams.get("to");
 50→  const presetParam = url.searchParams.get("preset") ?? "30d";
 51→
 52→  // Resolve date range
 53→  const now = new Date();
 54→  let fromDate: Date;
 55→  let toDate: Date = new Date(now);
 56→  toDate.setHours(23, 59, 59, 999);
 57→
 58→  if (fromParam && toParam) {
 59→    fromDate = new Date(fromParam);
 60→    fromDate.setHours(0, 0, 0, 0);
 61→    const parsedTo = new Date(toParam);
 62→    parsedTo.setHours(23, 59, 59, 999);
 63→    toDate = parsedTo;
 64→  } else {
 65→    const daysBack = presetParam === "7d" ? 7 : presetParam === "90d" ? 90 : 30;
 66→    fromDate = new Date(Date.now() - daysBack * 24 * 60 * 60 * 1000);
 67→    fromDate.setHours(0, 0, 0, 0);
 68→  }
 69→
 70→  const dateFilter = { gte: fromDate, lte: toDate };
 71→
 72→  const subscription = await db.subscription.findUnique({ where: { shop } });
 73→  const plan = getPlan(subscription?.planId ?? "free");
 74→  const canViewAnalytics = hasFeature(plan.id, "analytics");
 75→
 76→  if (!canViewAnalytics) {
 77→    return {
 78→      plan,
 79→      canViewAnalytics: false as const,
 80→      stats: null,
 81→      topChartsWithNames: [] as TopChart[],
 82→      dailyTrend: [] as DailyDataPoint[],
 83→      preset: presetParam,
 84→      fromDate: fromDate.toISOString().split("T")[0],
 85→      toDate: toDate.toISOString().split("T")[0],
 86→    };
 87→  }
 88→
 89→  const [
 90→    totalViews,
 91→    totalClicks,
 92→    totalRecommendations,
 93→    totalConverts,
 94→    topCharts,
 95→    rawEvents,
 96→  ] = await Promise.all([
 97→    db.analyticsEvent.count({ where: { shop, eventType: "view", createdAt: dateFilter } }),
 98→    db.analyticsEvent.count({ where: { shop, eventType: "click", createdAt: dateFilter } }),
 99→    db.analyticsEvent.count({ where: { shop, eventType: "recommend", createdAt: dateFilter } }),
100→    db.analyticsEvent.count({ where: { shop, eventType: "convert", createdAt: dateFilter } }),
101→    db.analyticsEvent.groupBy({
102→      by: ["sizeChartId"],
103→      where: { shop, eventType: "view", sizeChartId: { not: null }, createdAt: dateFilter },
104→      _count: { id: true },
105→      orderBy: { _count: { id: "desc" } },
106→      take: 5,
107→    }),
108→    db.analyticsEvent.findMany({
109→      where: { shop, eventType: "view", createdAt: dateFilter },
110→      select: { createdAt: true },
111→      orderBy: { createdAt: "asc" },
112→    }),
113→  ]);
114→
115→  // Build daily trend bucketed by day
116→  const dayBuckets: Record<string, number> = {};
117→  const diffMs = toDate.getTime() - fromDate.getTime();
118→  const diffDays = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
119→  for (let i = 0; i < Math.min(diffDays, 90); i++) {
120→    const d = new Date(fromDate.getTime() + i * 24 * 60 * 60 * 1000);
121→    const key = d.toISOString().split("T")[0];
122→    dayBuckets[key] = 0;
123→  }
124→  for (const ev of rawEvents) {
125→    const key = ev.createdAt.toISOString().split("T")[0];
126→    if (key in dayBuckets) dayBuckets[key]++;
127→  }
128→
129→  // Condense to max 30 bars for readability
130→  const bucketEntries = Object.entries(dayBuckets);
131→  const maxBars = 30;
132→  let dailyTrend: DailyDataPoint[];
133→  if (bucketEntries.length <= maxBars) {
134→    dailyTrend = bucketEntries.map(([date, value]) => ({
135→      label: new Date(date + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric" }),
136→      value,
137→    }));
138→  } else {
139→    // Group into weekly buckets
140→    const weekBuckets: Record<string, number> = {};
141→    for (const [date, count] of bucketEntries) {
142→      const d = new Date(date + "T12:00:00Z");
143→      const weekStart = new Date(d);
144→      weekStart.setDate(d.getDate() - d.getDay());
145→      const wk = weekStart.toISOString().split("T")[0];
146→      weekBuckets[wk] = (weekBuckets[wk] ?? 0) + count;
147→    }
148→    dailyTrend = Object.entries(weekBuckets).map(([date, value]) => ({
149→      label: new Date(date + "T12:00:00Z").toLocaleDateString("en-US", { month: "short", day: "numeric" }),
150→      value,
151→    }));
152→  }
153→
154→  // Resolve chart names
155→  const chartIds = topCharts.map((tc) => tc.sizeChartId).filter((id): id is string => id !== null);
156→  const charts = chartIds.length > 0
157→    ? await db.sizeChart.findMany({ where: { id: { in: chartIds }, shop }, select: { id: true, name: true } })
158→    : [];
159→
160→  const topChartsWithNames: TopChart[] = topCharts.map((tc, idx) => ({
161→    chartId: tc.sizeChartId,
162→    chartName: charts.find((c) => c.id === tc.sizeChartId)?.name ?? "Unknown",
163→    views: tc._count.id,
164→    rank: idx + 1,
165→  }));
166→
167→  // Funnel rates
168→  const clickRate = totalViews > 0 ? ((totalClicks / totalViews) * 100).toFixed(1) : "0";
169→  const recommendRate = totalClicks > 0 ? ((totalRecommendations / totalClicks) * 100).toFixed(1) : "0";
170→  const convertRate = totalRecommendations > 0 ? ((totalConverts / totalRecommendations) * 100).toFixed(1) : "0";
171→  const overallConvertRate = totalViews > 0 ? ((totalConverts / totalViews) * 100).toFixed(1) : "0";
172→
173→  return {
174→    plan,
175→    canViewAnalytics: true as const,
176→    stats: {
177→      totalViews,
178→      totalClicks,
179→      totalRecommendations,
180→      totalConverts,
181→      clickRate,
182→      recommendRate,
183→      convertRate,
184→      overallConvertRate,
185→    },
186→    topChartsWithNames,
187→    dailyTrend,
188→    preset: presetParam,
189→    fromDate: fromDate.toISOString().split("T")[0],
190→    toDate: toDate.toISOString().split("T")[0],
191→  };
192→};
