  62→export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  63→  const { session } = await authenticate.admin(request);
  64→  const shop = session.shop;
  65→  const id = params.id;
  66→
  67→  if (!id) throw new Response("Not found", { status: 404 });
  68→
  69→  if (id === "new") {
  70→    return {
  71→      chart: null as null,
  72→      assignments: [] as Assignment[],
  73→      isNew: true,
  74→    };
  75→  }
  76→
  77→  const chart = await db.sizeChart.findFirst({
  78→    where: { id, shop },
  79→    include: { assignments: true },
  80→  });
  81→
  82→  if (!chart) {
  83→    throw new Response("Not found", { status: 404 });
  84→  }
  85→
  86→  return {
  87→    chart: {
  88→      id: chart.id,
  89→      name: chart.name,
  90→      category: chart.category,
  91→      status: chart.status,
  92→      data: chart.data,
  93→      createdAt: chart.createdAt.toISOString(),
  94→      updatedAt: chart.updatedAt.toISOString(),
  95→    },
  96→    assignments: chart.assignments.map((a) => ({
  97→      id: a.id,
  98→      assignmentType: a.assignmentType,
  99→      assignmentValue: a.assignmentValue,
 100→    })),
 101→    isNew: false,
 102→  };
 103→};
