 268→function formatDate(iso: string): string {
 269→  return new Date(iso).toLocaleDateString("en-US", {
 270→    month: "short",
 271→    day: "numeric",
 272→    year: "numeric",
 273→    hour: "2-digit",
 274→    minute: "2-digit",
 275→  });
