 278→function makeDefaultData(): ChartData {
 279→  return {
 280→    headers: ["Size", "Chest", "Waist", "Hips"],
 281→    units: { default: "in", available: ["in", "cm"] },
 282→    rows: [
 283→      { Size: "S", Chest: "", Waist: "", Hips: "" },
 284→      { Size: "M", Chest: "", Waist: "", Hips: "" },
 285→      { Size: "L", Chest: "", Waist: "", Hips: "" },
 286→    ],
 287→  };
