 290→function parseChartData(raw: string): ChartData {
 291→  try {
 292→    const parsed = JSON.parse(raw) as ChartData;
 293→    if (
 294→      Array.isArray(parsed.headers) &&
 295→      parsed.units &&
 296→      Array.isArray(parsed.rows)
 297→    ) {
 298→      return parsed;
 299→    }
 300→  } catch {
 301→    // fall through
 302→  }
 303→  return makeDefaultData();
 304→}
