 325→
 326→  const updateHeader = (headerIndex: number, value: string) => {
 327→    const oldHeader = data.headers[headerIndex];
 328→    const newHeaders = data.headers.map((h, i) =>
 329→      i === headerIndex ? value : h,
 330→    );
 331→    const newRows = data.rows.map((row) => {
 332→      const newRow: Record<string, string> = {};
 333→      data.headers.forEach((h, i) => {
 334→        const key = i === headerIndex ? value : h;
 335→        newRow[key] = row[h] ?? "";
 336→      });
 337→      return newRow;
 338→    });
 339→    onChange({ ...data, headers: newHeaders, rows: newRows });
 340→    void oldHeader;
 341→  };
 342→
 343→  const addRow = () => {
 344→    const emptyRow: Record<string, string> = {};
