 734→          </InlineStack>
 735→          <InlineStack align="space-between">
 736→            <Text as="span" variant="bodySm" tone="subdued">Assignments</Text>
 737→            <Text as="span" variant="bodySm">{assignmentCount}</Text>
 738→          </InlineStack>
 739→        </BlockStack>
 740→
 741→        {/* Hint */}
 742→        <Box
 743→          padding="300"
 744→          background="bg-surface-secondary"
 745→          borderRadius="200"
 746→        >
 747→          <Text as="p" variant="bodySm" tone="subdued">
 748→            Add the Size Chart widget block in your theme editor to display charts on product pages.
 749→          </Text>
 750→        </Box>
 751→      </BlockStack>
 752→    </Card>
 753→  );
 754→}
